/// `battle.yaml`.
const battleYaml = r'''
# Default battle settings. All numbers are PLACEHOLDERS to be tuned.
# These are settings of a battle (chosen when an admin creates it); these values are the defaults.
# `ap.max`, `victory` and `storage` hold battle-wide rule values (decisions 45, 110, 167); they are not declared battle settings.
version: 10

# Commander death (decisions 80, 125): no respawn delay; the commander resurrects in storage.
# All units of his section on the field (carried ones included) go instantly to storage.
commander_death:
  xp_loss_share: 0.25        # share of the commander's own UNSPENT XP lost, from his earned XP too (decision 207); his level is never lost
  ap_loss_share: 1.0         # share of ap_max removed from each stored unit (1.0 = AP to 0)
  morale_loss: 20            # morale points removed from each stored unit

ap:
  max: 30                    # AP maximum of every unit; each unit's ap_max in data/units.yaml equals it (decision 167)
  # AP recovery (decisions 168, 172): AP every unit recovers per hour. Special events may use another rate.
  recovery_per_hour: 1

# Start of every battle of a war (decision 83)
battle_start:
  restore_ap: full
  restore_hp: full
  restore_morale: base       # data/combat.yaml morale.base

# Teams (decision 103): balanced by team power at each battle.
teams:
  count: 2                   # 2..5 (decision 84)

# Newcomers (SOC-03, SOC-07): a new player picks his guild among this many, drawn at random.
newcomers:
  guilds_offered: 4

# Relic capture (decisions 97, 170)
capture:
  duration_s: 1800           # starts when the pot is full
  pot_ap: 50                 # team pot: units in the radius add contribution_ap per action
                             # an enemy entering the radius empties it, even with no unit of the team inside (decision 176)
  contribution_ap: 5
  radius_m: 30               # same radius to capture and to block

# HQ (decisions 109, 177): moves on its own on the manager's order, paying from its own AP.
hq:
  hp: 1000                   # armor type: hq (decision 114)
  ap_max: 30                 # recovers at ap.recovery_per_hour
  ap_per_m: 0.2              # placeholder: flat grass, times the push profile (data/terrain.yaml)
  speed_m_per_h: 5           # placeholder: slower than any unit
  hit_box_m: { width: 20, length: 20, height: 8 }   # placeholder: first-person shots (decision 183)

# Victory (decisions 45, 46c): hold relics_to_hold relics for hold_s, or be the last HQ.
victory:
  relics_to_hold: 5
  hold_s: 86400

# Storage and deployment (decision 110).
storage:
  store_radius_m: 10         # a unit this close to its storage place is stored at once
  recall_s: 21600            # recall from anywhere else (6 h); nothing stops it
  deploy_ap: 10              # AP a unit pays to deploy
  deploy_block_radius_m: 20  # an enemy this close to the storage place blocks deployment

# Server-managed sections (decisions 160, 196, 228, 229): each unit that sees an enemy unit within its
# weapon's range fires at the nearest with fire_chance at each check. Checks fall every
# check_interval_s from the battle start; not when an enemy enters range.
server_managed:
  fire_chance: 0.5           # placeholder
  check_interval_s: 1800     # 30 minutes (decision 160)

# Weather (decision 90): changes randomly, per map. No day/night.
weather:
  mode: random
  states: [clear, rain, fog, snow]   # data/terrain.yaml weather

# Full section storage (decisions 120, 204): once no unit of a section is left on the field, the
# section cannot deploy again for this long, from the moment the last one left it. Not after a
# commander's death (decision 125).
section_redeploy_lock_s: 86400
''';

/// `combat.yaml`.
const combatYaml = r'''
# Draft combat table. All numbers are PLACEHOLDERS to be tuned.
# damage = weapon.base_damage * multipliers[weapon_type][target.armor_type]
#          * weapon.airborne_factor   (only when the target is flying)
# Unit `attack` and `defense` do NOT change damage: they change the chance to hit (see hit_chance).
version: 14

armor_types: [infantry, light_vehicle, heavy_vehicle, structure, hq, relic]
# Every unit declares one armor_type (data/units.yaml).
# Flying is NOT an armor type: it is a unit capability (see data/units.yaml).
# A flying unit keeps a normal armor type; weapons apply their airborne_factor on top.

# Weapons are items (decision 52). A unit has ONE weapon slot. Each unit type lists the
# weapon types it may use and comes with a default weapon (data/units.yaml).
#
# Weapon characteristics
#   base_damage, range_m, ap_per_shot
#   rate_of_fire_rpm   firing speed: shots per minute while the magazine is not empty
#                      (not used by 1-round weapons: they fire once per reload_time_s, decision 150)
#   magazine_capacity  cartridge capacity: shots before a reload is needed
#   reload_time_s      loading speed: seconds to load a full magazine (no AP cost)
#   unload_time_s      unloading speed: seconds to unload the weapon (no AP cost)
#   move_while_loaded  true: the unit can move with the weapon loaded
#                      false: the weapon must be unloaded before the unit moves
#   airborne_factor    damage multiplier against a flying target (0 = cannot hit it)
#   projectile_speed_mps  speed of a first-person shot (decision 183). Not set for indirect fire
#                      (artillery) or a weapon that never misses (explosive charge).
#   base_accuracy      starting hit chance under orders/AI, before factors (decision 65);
#                      a weapon with never_misses has none (decision 152)
#   indirect_fire      true: may target a ground position its section sees or a radio relays (decision 62)
#   never_misses       true: no hit roll, the charge goes off on the aimed point (decision 152)
#   range_m is a cap: a unit only fires at targets it sees itself (decision 59),
#   except indirect_fire weapons.
# Values are the accepted starting point for the rules core (decision 69).
weapon_types:
  rifle:       { base_damage: 12, range_m: 400,  ap_per_shot: 2,  base_accuracy: 0.70, rate_of_fire_rpm: 40,  magazine_capacity: 10,  reload_time_s: 3,  unload_time_s: 2,  move_while_loaded: true,  projectile_speed_mps: 900, airborne_factor: 0.2 }
  machine_gun: { base_damage: 8,  range_m: 300,  ap_per_shot: 1,  base_accuracy: 0.50, rate_of_fire_rpm: 500, magazine_capacity: 100, reload_time_s: 8,  unload_time_s: 4,  move_while_loaded: true,  projectile_speed_mps: 850, airborne_factor: 0.4 }
  anti_tank:   { base_damage: 60, range_m: 250,  ap_per_shot: 10, base_accuracy: 0.60, rate_of_fire_rpm: 6,   magazine_capacity: 1,   reload_time_s: 6,  unload_time_s: 3,  move_while_loaded: true,  projectile_speed_mps: 300, airborne_factor: 0.1 }
  artillery:   { base_damage: 40, range_m: 1200, ap_per_shot: 15, base_accuracy: 0.40, rate_of_fire_rpm: 4,   magazine_capacity: 1,   reload_time_s: 10, unload_time_s: 30, move_while_loaded: false, airborne_factor: 0.0, splash_radius_m: 8, deforms_terrain: true, indirect_fire: true }
  anti_air:    { base_damage: 30, range_m: 800,  ap_per_shot: 6,  base_accuracy: 0.60, rate_of_fire_rpm: 60,  magazine_capacity: 20,  reload_time_s: 10, unload_time_s: 15, move_while_loaded: false, projectile_speed_mps: 600, airborne_factor: 2.0 }
  explosive:   { base_damage: 80, range_m: 5,    ap_per_shot: 20, rate_of_fire_rpm: 1,   magazine_capacity: 1,   reload_time_s: 10, unload_time_s: 5,  move_while_loaded: true,  airborne_factor: 0.0, splash_radius_m: 4, never_misses: true }   # engineer charge (decision 152)
# Weapon prices: data/economy.yaml (the default weapon is included in the unit price).

multipliers:
  rifle:       { infantry: 1.0, light_vehicle: 0.3, heavy_vehicle: 0.05, structure: 0.1, hq: 0.05, relic: 0 }
  machine_gun: { infantry: 1.2, light_vehicle: 0.4, heavy_vehicle: 0.05, structure: 0.1, hq: 0.05, relic: 0 }
  anti_tank:   { infantry: 0.5, light_vehicle: 1.5, heavy_vehicle: 1.2,  structure: 0.8, hq: 0.6,  relic: 0 }
  artillery:   { infantry: 1.0, light_vehicle: 1.0, heavy_vehicle: 0.7,  structure: 1.2, hq: 1.0,  relic: 0 }
  anti_air:    { infantry: 0.3, light_vehicle: 0.3, heavy_vehicle: 0.1,  structure: 0.1, hq: 0.05, relic: 0 }
  explosive:   { infantry: 1.5, light_vehicle: 1.2, heavy_vehicle: 1.0,  structure: 2.0, hq: 1.5,  relic: 0 }

# Splash (decision 136): only bombard attacks have splash: weapons with a splash_radius_m
# (artillery, explosive charge). Artillery rolls its hit chance; the explosive charge never misses (decision 152).
# Every unit within the weapon's splash_radius_m of the impact point is hit at once, without its
# own hit roll, friend or foe. Damage falls off linearly with the distance, from 1 at the impact
# point to damage_factor_at_edge at splash_radius_m.
# Splash damage does not depend on the weapon's range.
splash:
  falloff: linear
  damage_factor_at_edge: 0.0     # placeholder

# Missed artillery shot (decision 154): it lands in a random direction from the aimed point,
# at miss_importance x max_m. The landing point stays within range_m of the artillery: a point
# beyond it is moved back toward the artillery to range_m.
# miss_importance = (roll - chance) / (1 - chance): 0 for a near miss, 1 for the worst miss.
miss_scatter:
  max_m: 100                     # placeholder

friendly_fire: { enabled: true, damage_factor: 1.0 }

# Units carried by a transport (decision 81): each takes this share of every hit on the
# transport, recomputed with its own armor type. Ejection damage at transport death: 37e.
transport:
  carried_damage_share: 0.25
  ejection_damage_share_of_max_hp: 0.5   # placeholder, explosion damage when ejected (decision 137)

# Morale (decision 70): 0..100, starts at base, changes only through events, no drift.
morale:
  range: [0, 100]
  base: 50                         # value of a newly bought unit
  events:                          # placeholders
    commander_aura_per_min: +2     # while inside its own commander's aura_radius
    nearby_enemy_killed: +5        # within nearby_radius_m
    nearby_ally_killed: -8
    outnumbered_per_min: -3        # local enemy/ally ratio above outnumbered_ratio
  nearby_radius_m: 50
  outnumbered_ratio: 1.5

# 0 HP with the final blow from a commander (decisions 37f, 72)
# p_spared = k * ((100 - morale)/100 + (1 - ap/ap_max)) / 2
# spared -> defection or prisoner by defection_share; defection needs room in the
# attacking section, otherwise prisoner. Not spared -> death.
zero_hp:
  k: 0.6
  defection_share: 0.5
  only_when_final_blow_by: commander
  target: enemy                    # friendly fire never spares a unit (decision 131)
  never_spared: [commander, encampment]   # decision 149

# Prisoners (decision 73): stored instantly in the captor section's storage.
prisoners:
  held_in: captor_prisoner_storage   # separate and unlimited (decision 94)
  can_escape: false
  ransom_fee: 0                    # ransom goes entirely to the captor section
  at_war_end: lost

# Ammo (decision 54): unlimited. Only the loaded magazine is limited.
# A reload always gives a full magazine; rounds left in it are discarded.
ammo:
  unlimited: true
  reload_discards_remaining: true

# Hit chance under orders / AI (decisions 58, 65)
# chance = weapon.base_accuracy
#          * (1 + (attacker.attack - target.defense) / 100)
#          * distance_factor * cover_factor * size_factor * speed_factor
#          * indirect_factor (indirect fire only)
#          * morale_factor   (attacker morale, decision 71)
#          clamped to [min, max]
# A weapon with never_misses (the explosive charge) has no hit chance (decision 152).
# Cover only lowers hit chance; it never reduces damage (decision 65).
hit_chance:
  clamp: { min: 0.05, max: 0.95 }
  distance_factor: { at_zero: 1.0, at_max_range: 0.5 }   # linear between 0 and range_m
  cover_factor: { none: 1.0, partial: 0.5, full: 0.0 }   # full: the clamp still gives 5 % (decision 135)
  size_factor:  { infantry: 0.8, light_vehicle: 1.0, heavy_vehicle: 1.2, structure: 1.5, hq: 2.0, relic: 2.0 }  # by target armor_type
  speed_factor: { per_mps: 0.02, min: 0.5 }   # 1 - per_mps * target speed, not below min
  indirect_factor: 0.5
  morale_factor: { at_0: 0.9, at_100: 1.1 }   # linear in attacker morale

# First-person aim (decision 58): attack tightens spread and sway.
aim:
  base_spread_deg: 2.0                # placeholder
  spread_reduction_per_attack: 0.01   # fraction of spread removed per attack point (placeholder)
  min_spread_deg: 0.2                 # placeholder
  # Morale also scales spread (decision 95): spread / hit_chance.morale_factor

# Dropped weapons (decisions 53, 63)
dropped_weapons:
  pickup_ap: 5                  # AP to pick up a dropped weapon (exception to time-only handling)
  despawn_after_s: 600          # placeholder

# Weapon swap at storage (decisions 53, 55, 134): time only, no AP. Bought and swapped-out
# weapons are kept in the section's storage until a unit takes one (decision 151).
weapon_swap:
  time_s: 5

ap:
  # AP recovery rate: ap.recovery_per_hour in data/battle.yaml (decisions 168, 172).
  at_zero: act_at_regen_rate    # decision 56: movement continues at the AP recovery speed; paid actions wait for enough AP
  # An action that is not in the unit's units.yaml `actions` is refused (decision 132).
  costs_ap: [shot, move, push, pickup_weapon, role_actions]
  time_only: [reload, unload, swap_weapon, land, take_off]   # decisions 55, 68

# Role actions (decision 66): fixed AP paid up front, then a duration. Capture is paid into a team pot (decision 170).
# A unit must have the AP to start. Interrupted: AP lost, progress kept.
# Constructions (build) have their own AP/time per structure: data/terrain.yaml (decision 113).
actions:
  heal:    { instant: true, targets: friendly_except_hq }   # AP and HP from the healer's role (units.yaml, decisions 91, 139)
  repair:  { ap: 10, duration_s: 10, hp_restored: 50, targets: friendly_except_hq }   # placeholder; structures too (decisions 13, 139)
  capture: { settings: data/battle.yaml, progress_owner: team }   # decisions 97, 140, 170, 173
  interruption: { ap_refund: false, progress_kept: true, resume_cost: proportional_to_remaining, capture_progress_kept: false }   # decisions 67, 97

# Pushing a relic (decisions 66, 98, 138, 171, 175): at least min_pushers units that can push
# (units.yaml actions). The relic moves at speed_m_per_h while its push pot holds AP. The HQ is not pushed (data/battle.yaml hq).
# Each metre pushed costs pot_ap_per_m from the pot, times the ground and signed slope multipliers
# of the push profile (data/terrain.yaml, decision 175). Pushers add contribution_ap per action, as often as they like.
# An empty pot stops the push; it stops too while fewer than min_pushers push.
# One pot per relic, for its owner; it empties when another team captures the relic or it falls (decision 176).
push:
  speed_m_per_h: 5              # decision 138
  pot_ap_per_m: 10              # placeholder: flat grass (decision 175)
  contribution_ap: 5            # AP a pusher adds to the pot per action (decision 171)
  min_pushers: 10               # decision 98
  pot_empty: stops              # decision 171
  # Crushing (decisions 115, 138): with min_pushers + n pushers the relic crushes up to n units
  # in its path; with more blocking units than n it stops. A crushed unit dies.
  crush_units_per_extra_pusher: 1
  crush: kills
''';

