const medalsYaml = r'''
# Medals and statistics (decisions 105, 143). Thresholds are PLACEHOLDERS except the designer's example.
version: 1
tiers: [bronze, silver, gold]
points: { bronze: 1, silver: 3, gold: 10 }   # decision 121; HQ manager = most points, tie -> most commander XP

# One medal track per kind of kill (by target unit type) and per kind of action.
kills:
  commander: { bronze: 5, silver: 25, gold: 100 }   # bronze value from the designer's example
  default:   { bronze: 20, silver: 100, gold: 500 } # every other unit type
actions:
  default:   { bronze: 50, silver: 250, gold: 1000 }
  kinds: [hit, build, repair, heal, capture, observe, push, hq_hit, prisoner_taken, defection_caused]

# Friendly kills (decision 231): a track of their own; they never count toward a kill medal.
friendly_kills: { bronze: 5, silver: 25, gold: 100 }   # placeholder

# Hit rates far above the norm (decision 230), flagged for moderation: over a battle-day, a player's
# hit rate with a weapon on first-person shots, this many standard deviations above the mean of all
# players with that weapon, after at least min_shots shots.
hit_rate_flag:
  sigmas: 3
  min_shots: 50
''';

/// `terrain.yaml`.
const terrainYaml = r'''
# Draft terrain table. All numbers are PLACEHOLDERS to be tuned.
# ap_multiplier: factor on the unit's ap_per_m (data/units.yaml), per movement class and terrain,
#   before the slope factor. Grass is 1.0 for every class (decision 169). Neither changes move_speed (decision 180).
# null means impassable for that movement class or profile.
version: 7
movement_classes: [foot, wheeled, tracked]
# The `flying` and `sail` entries below are movement PROFILES, used by units that have the
# flying or sail capability (data/units.yaml). They are not movement classes.
# `push` is the profile of a pushed relic and of the moving HQ (decisions 175, 177).
# A landed flying unit uses its ground movement_class (decision 68).
# Flying altitude limit: the map's highest terrain point + this many metres (decision 142).
flying_max_above_highest_terrain_m: 10

slope:
  # Slope is signed (decision 133): positive uphill, negative downhill.
  # cost multiplier = max(min_multiplier, 1 + slope_degrees * factor)
  # Impassable when the slope, up or down, is steeper than max_degrees. Relics and the HQ use the push row.
  foot:    { factor: 0.05, max_degrees: 45, min_multiplier: 0.5 }   # min_multiplier: placeholder
  wheeled: { factor: 0.10, max_degrees: 25, min_multiplier: 0.5 }
  tracked: { factor: 0.07, max_degrees: 35, min_multiplier: 0.5 }
  flying:  { factor: 0.0,  max_degrees: 90, min_multiplier: 1.0 }
  sail:    { factor: 0.0,  max_degrees: 90, min_multiplier: 1.0 }   # water is flat
  push:    { factor: 0.07, max_degrees: 35, min_multiplier: 0.5 }   # placeholder (decision 175)

# Vision (decision 59)
# effective_vision = vision_range * weather.vision_factor * terrain[observer].vision_factor
#                    + height_bonus ; then hard line-of-sight blockers apply.
vision:
  height_bonus_m_per_m: 2.0     # extra vision metres per metre the observer stands above the target
  height_bonus_max_m: 150
  # Forest concealment (decision 87): each metre of forest crossed by the sight line
  # removes this many metres of the observer's effective vision. A flying observer's
  # line crosses less forest, so it sees forest targets more easily.
  forest_vision_cost_per_m: 4.0
  destroyed_objects_block: false

# Weather is a per-battle state that changes randomly, per map (decisions 59, 90; data/battle.yaml).
weather:
  clear: { vision_factor: 1.0 }
  rain:  { vision_factor: 0.7 }
  fog:   { vision_factor: 0.4 }
  snow:  { vision_factor: 0.6 }

terrain:
  grass:
    blocks_los: false
    vision_factor: 1.0
    ap_multiplier: { foot: 1.0, wheeled: 1.0, tracked: 1.0, flying: 0.5, sail: null, push: 1.0 }
  forest_floor:           # ground under trees
    blocks_los: false     # partial: forest concealment, see vision.forest_vision_cost_per_m
    vision_factor: 0.5    # observer standing in a forest sees less far
    ap_multiplier: { foot: 1.5, wheeled: 3.0, tracked: 2.5, flying: 0.5, sail: null, push: null }
  sand:
    blocks_los: false
    vision_factor: 1.0
    ap_multiplier: { foot: 1.5, wheeled: 2.0, tracked: 1.5, flying: 0.5, sail: null, push: 1.5 }
  mud:
    blocks_los: false
    vision_factor: 1.0
    ap_multiplier: { foot: 2.0, wheeled: 4.0, tracked: 2.0, flying: 0.5, sail: null, push: 2.0 }
  rock:
    blocks_los: false
    vision_factor: 1.0
    ap_multiplier: { foot: 1.5, wheeled: 2.0, tracked: 1.5, flying: 0.5, sail: null, push: 1.5 }
  road:
    blocks_los: false
    vision_factor: 1.0
    ap_multiplier: { foot: 0.7, wheeled: 0.4, tracked: 0.5, flying: 0.5, sail: null, push: 0.5 }
  town_street:
    blocks_los: false
    vision_factor: 0.8
    ap_multiplier: { foot: 0.8, wheeled: 0.6, tracked: 0.7, flying: 0.5, sail: null, push: null }
  mountain:
    blocks_los: true
    vision_factor: 1.0
    ap_multiplier: { foot: 3.0, wheeled: null, tracked: null, flying: 0.5, sail: null, push: null }
  river:
    blocks_los: false
    vision_factor: 1.0
    ap_multiplier: { foot: null, wheeled: null, tracked: null, flying: 0.5, sail: 0.8, push: null }
