  lake:
    blocks_los: false
    vision_factor: 1.0
    ap_multiplier: { foot: null, wheeled: null, tracked: null, flying: 0.5, sail: 0.6, push: null }
    crossable_by: [sail]   # boats and amphibious units (decision 86)
  floating_island_ground:
    blocks_los: false
    vision_factor: 1.0
    ap_multiplier: { foot: 1.0, wheeled: 1.0, tracked: 1.0, flying: 0.5, sail: null, push: 1.0 }
    access: [flying, bridge, ladder]

# Craters (decision 85)
craters:
  max_depth_m: 20
  fillable_by_engineers: false
  # A shot of a weapon with deforms_terrain digs a bowl at its impact point, as wide as its
