/// `units.yaml`.
const unitsYaml = r'''
# Draft units table. All numbers are PLACEHOLDERS to be tuned.
version: 14

# AP max is the same for every unit: data/battle.yaml ap.max (decision 167). AP recovery is one rate for all units, a battle setting (data/battle.yaml, decision 172).
# ap_per_m: AP per metre on flat ground (decisions 169, 181). Terrain, movement class and slope multiply it
#   (data/terrain.yaml). move_speed is the time per metre, in m/s; it does not set the AP cost.
common_stats: [hp, ap_max, ap_per_m, attack, defense, move_speed, vision_range, movement_class, armor_type, hit_box_m, morale]
# hit_box_m: hit volume for first-person shots, in metres, close to the real unit (decision 183).
# attack:   accuracy. Raises hit chance under orders/AI, tightens spread in first-person aim.
# defense:  evasion. Lowers the chance of being hit. Neither stat changes damage (decision 58).
# armor_type: one of data/combat.yaml armor_types. Damage = weapon x weapon-vs-armor table.
# vision_range: metres, before weather, terrain and height modifiers (data/terrain.yaml, decision 59).
# movement_class: foot | wheeled | tracked
# capabilities (optional list): abilities a unit has on top of its category and movement class.
#   flying: the unit moves with the `flying` profile of data/terrain.yaml and is hit as a
#           flying target (weapon airborne_factor, data/combat.yaml). Flying is not a unit
#           category, not a movement class and not an armor type.
#   sail:   the unit moves on water with the `sail` profile of data/terrain.yaml (decision 86).
#           With no ground movement_class it is water-only (a boat); with a ground
#           movement_class as well it is amphibious.
# weight: every unit has a weight; transports carry by weight (decision 91).
# weapons (decision 52): one slot. `default` comes with the unit (included in its price);
#   `allowed` lists the weapon types it may equip at storage or pick up on the field.
#   Allowed lists are placeholders.
# morale: 0..100, starts at data/combat.yaml morale.base. See specs/70-combat-and-ap.md.
# actions (decision 132): what the unit can do besides moving and shooting:
#   capture, push, build, repair, heal, observe. An order for any other action is refused.
#   No listed action costs more AP up front than the unit's ap_max. Lists: decision 145.
#   Heal and repair work on every friendly unit except the HQ (decision 139).

units:
  commander:
    category: commander
    movement_class: foot
    armor_type: infantry
    hit_box_m: { width: 0.6, length: 0.6, height: 1.8 }
    base: { weight: 1, hp: 200, ap_max: 30, ap_per_m: 1.0, attack: 15, defense: 10, move_speed: 5, vision_range: 150 }
    weapons: { default: rifle, allowed: [rifle, machine_gun] }
    actions: [capture, push]
    role: { aura_radius: 30 }  # section size cap and storage: progression.section_size
    permadeath: false          # resurrects in storage at once (decisions 80, 125)
  soldier:
    category: soldier
    movement_class: foot
    armor_type: infantry
    hit_box_m: { width: 0.6, length: 0.6, height: 1.8 }
    base: { weight: 1, hp: 100, ap_max: 30, ap_per_m: 1.0, attack: 12, defense: 5, move_speed: 5, vision_range: 150 }
    weapons: { default: rifle, allowed: [rifle, machine_gun, anti_tank, anti_air] }
    actions: [capture, push]
  engineer:
    category: engineer
    movement_class: foot
    armor_type: infantry
    hit_box_m: { width: 0.6, length: 0.6, height: 1.8 }
    base: { weight: 1, hp: 90, ap_max: 30, ap_per_m: 1.0, attack: 6, defense: 4, move_speed: 4, vision_range: 120 }
    weapons: { default: rifle, allowed: [rifle, explosive] }
    actions: [capture, push, build, repair]
    role: { build: [bridge, reinforced_bridge, ladder, wall, road_segment, trap], repair: true }
  scout:
    category: scout
    movement_class: foot
    armor_type: infantry
    hit_box_m: { width: 0.6, length: 0.6, height: 1.8 }
    base: { weight: 1, hp: 70, ap_max: 30, ap_per_m: 1.0, attack: 5, defense: 8, move_speed: 7, vision_range: 300 }
    weapons: { default: rifle, allowed: [rifle] }
    actions: [capture, push, observe]
    role: { reports_to_radio: true, observe: { vision_bonus_m: 30, duration_s: 1800, ap: 10, can_move: false } }   # decision 119
  medic:
    category: soldier          # decision 60: a medic is a soldier with a heal role
    movement_class: foot
    armor_type: infantry
    hit_box_m: { width: 0.6, length: 0.6, height: 1.8 }
    base: { weight: 1, hp: 80, ap_max: 30, ap_per_m: 1.0, attack: 4, defense: 3, move_speed: 5, vision_range: 120 }
    weapons: { default: rifle, allowed: [rifle] }
    actions: [capture, push, heal]
    role: { heal: 20, heal_ap: 10, earns_money_when_healing: true }   # instant heal: 10 AP restores 20 HP (decision 91)
  artillery:
    category: artillery
    movement_class: tracked
    armor_type: light_vehicle
    hit_box_m: { width: 3.5, length: 7.0, height: 3.0 }
    base: { weight: 8, hp: 150, ap_max: 30, ap_per_m: 0.2, attack: 10, defense: 2, move_speed: 12, vision_range: 100 }
    weapons: { default: artillery, allowed: [artillery] }   # range, splash, deformation: weapon data
    actions: [capture, push]
  radio:
    category: radio
    movement_class: tracked
    armor_type: structure
    hit_box_m: { width: 3.0, length: 6.0, height: 3.0 }
    base: { weight: 10, hp: 250, ap_max: 30, ap_per_m: 0.2, attack: 0, defense: 0, move_speed: 5, vision_range: 80 }
    weapons: { default: null, allowed: [] }   # unarmed: cannot attack (decision 64)
    actions: []                 # unarmed, no capture, no push (decision 145)
    role: { relay_range: 150, shares_with: all_sections_of_team, transportable: false }   # starting range, evolves via tree
    purchasable_by: commander   # normal unit: destructible, can be captured, stored (decision 76)

  encampment:                   # guild camp (decision 141)
    category: encampment          # guild storage place with a portal (decisions 28, 46h4)
    owner: guild_commander        # a unit of the guild chief's section
    counts_in_section_cap: false  # outside the cap, and never stored (decision 127) but between battles and at its team's elimination (decisions 208, 212)
    storable: false
    movement_class: tracked       # moves slowly on its own; cannot fly or reach floating islands (decision 88)
    armor_type: structure
    hit_box_m: { width: 8.0, length: 12.0, height: 4.0 }
    base: { weight: 50, hp: 300, ap_max: 30, ap_per_m: 0.2, attack: 0, defense: 0, move_speed: 1, vision_range: 50 }
    weapons: { default: null, allowed: [] }
    actions: [heal]
    role: { heal: 20, heal_ap: 10, earns_money_when_healing: true, transportable: false }   # placeholders (decision 145)
    purchasable_by: guild_commander   # price: data/economy.yaml; armor type structure (decision 114)

  # Roster v1 additions (decision 61)
  jeep:
    category: vehicle
    movement_class: wheeled
    armor_type: light_vehicle
    hit_box_m: { width: 1.9, length: 4.5, height: 1.8 }
    base: { weight: 4, hp: 180, ap_max: 30, ap_per_m: 0.1, attack: 8, defense: 6, move_speed: 28, vision_range: 150 }
    weapons: { default: machine_gun, allowed: [machine_gun] }
    actions: [capture, push]
  tank:
    category: vehicle
    movement_class: tracked
    armor_type: heavy_vehicle
    hit_box_m: { width: 3.6, length: 7.5, height: 2.5 }
    base: { weight: 12, hp: 600, ap_max: 30, ap_per_m: 0.2, attack: 10, defense: 1, move_speed: 14, vision_range: 120 }
    weapons: { default: anti_tank, allowed: [anti_tank, machine_gun] }
    actions: [capture, push]
  truck:
    category: transport
    movement_class: wheeled
    armor_type: light_vehicle
    hit_box_m: { width: 2.5, length: 8.0, height: 3.0 }
    base: { weight: 8, hp: 250, ap_max: 30, ap_per_m: 0.1, attack: 0, defense: 3, move_speed: 22, vision_range: 100 }
    weapons: { default: null, allowed: [] }   # unarmed: cannot attack (decision 64)
    actions: [capture, push]
    role: { max_total_weight: 6, max_unit_weight: 2 }   # decision 91
  helicopter:                   # base move_speed at most the jeep's; evolution may exceed it (decisions 174, 178)
    category: vehicle
    movement_class: wheeled     # ground class used while landed (decision 68)
    capabilities: [flying]
    flying: { land_time_s: 8, take_off_time_s: 8 }   # placeholder; max altitude is set by the map
    armor_type: light_vehicle
    hit_box_m: { width: 3.0, length: 14.0, height: 4.0 }
    base: { weight: 6, hp: 200, ap_max: 30, ap_per_m: 0.1, attack: 10, defense: 10, move_speed: 28, vision_range: 300 }
    weapons: { default: machine_gun, allowed: [machine_gun, anti_tank] }
    actions: [capture]          # does not push (decision 145)
  boat:                         # base move_speed at most the tank's; evolution may exceed it (decisions 174, 178)
    category: transport
    movement_class: null        # water only (sail without ground class)
    capabilities: [sail]
    armor_type: light_vehicle
    hit_box_m: { width: 3.0, length: 9.0, height: 2.0 }
    base: { weight: 6, hp: 200, ap_max: 30, ap_per_m: 0.1, attack: 8, defense: 4, move_speed: 11, vision_range: 150 }
    weapons: { default: machine_gun, allowed: [machine_gun] }
    actions: [capture]          # water only: does not push (decision 145)
    role: { max_total_weight: 4, max_unit_weight: 2 }   # boards/unloads next to the shore (decision 86)

# Progression (decisions 77-79)
progression:
  xp_sources:                     # placeholders
    hit: 2
    kill: 20
    role_action: 5                # per completed build, repair, heal, spotting report
    capture: 50                   # shared by the AP each unit put into the pot, on success (decision 179)
    hq_hit: 2                     # per hit on an enemy HQ, not scaled by target XP (decision 224)
    hq_destruction: 10            # the shot that destroys an enemy HQ earns hq_hit too (decision 224)
                                  # no XP for time near the commander (decision 199)
  target_scaling:                 # hit/kill XP x min(cap, 1 + target_xp / max(attacker_xp, 1)), earned XP (decision 197)
    cap: 3.0
  diminishing:                    # same target or same build spot, within the window
    window_s: 600
    factor_per_repeat: 0.5
    same_spot_radius_m: 10        # a build this close to one of the unit's builds is at the same spot (decision 198)
  friendly_hits_give_xp: false
  victory_xp: 1                   # per unit of the winning team; normal section share applies (decision 92)
  section_xp_share: 0.2           # share of each XP point earned by a unit, moved to section XP
  # Section XP sets the commander level. It cannot be spent on stats.
  # Section size (decision 127). The cap counts ACTIVE units (on the field), the commander included:
  #   cap = cap_at_level_1 + floor((level - 1) / extra_unit_every_levels)   (levels 1-5: 5, 6-10: 6...)
  # A section owns at most max_units_factor x cap units (active + stored), which is also its
  # storage capacity, so all its units always fit in storage. The guild camp (encampment) and
  # the HQ are not counted and cannot be stored.
  section_size:
    cap_at_level_1: 5
    extra_unit_every_levels: 5
    max_units_factor: 2
  guild_creation_min_level: 10    # commander level a section needs to create a guild (decision 155)
  # Guild size (SOC-47, decision 221): the guild's level comes from every XP point its sections'
  # units earn while in the guild, on the commander_levels curve below. Placeholders.
  #   max sections = sections_at_level_1 + floor((level - 1) / extra_section_every_levels)   (16 at level 60)
  guild_size:
    sections_at_level_1: 5
    extra_section_every_levels: 5
  # Commander levels (decision 144), 1 to max_level. section_xp[i] is the section XP needed to
  # reach level i + 1. Placeholder curve: going from level n to n + 1 costs 500 x n.
  # Cap from section_size: levels 1-5: 5, 6-10: 6, ..., 56-60: 16.
  commander_levels:
    max_level: 60
    section_xp: [
      0, 500, 1500, 3000, 5000, 7500, 10500, 14000, 18000, 22500,   # levels 1-10
      27500, 33000, 39000, 45500, 52500, 60000, 68000, 76500, 85500, 95000,   # levels 11-20
      105000, 115500, 126500, 138000, 150000, 162500, 175500, 189000, 203000, 217500,   # levels 21-30
      232500, 248000, 264000, 280500, 297500, 315000, 333000, 351500, 370500, 390000,   # levels 31-40
      410000, 430500, 451500, 473000, 495000, 517500, 540500, 564000, 588000, 612500,   # levels 41-50
      637500, 663000, 689000, 715500, 742500, 770000, 798000, 826500, 855500, 885000,   # levels 51-60
    ]

# Evolution trees (decisions 78, 118)
# Each unit spends its OWN XP on its own tree, commander included. Nodes are permanent
# (no respec) and never exclude each other. Trees give STAT BONUSES ONLY (no abilities).
# Every evolved stat is capped at 300 % of its base value (x3).
# Default tree, applied to every unit type: for each listed stat, a chain of steps;
# step n adds step_bonus of the base value and costs cost_base * n XP; step n requires step n-1.
trees:
  stat_cap_of_base: 3.0
  default:
    stats: [hp, attack, defense, move_speed, vision_range]   # AP is not evolvable (decision 167)
    step_bonus: 0.10            # +10 % of base per step -> 20 steps to reach the cap
    cost_base: 100              # placeholder
  overrides:                    # extra stats for some unit types
    radio:  { extra_stats: [relay_range] }
    commander: { extra_stats: [aura_radius] }
    truck:  { extra_stats: [max_total_weight] }
    boat:   { extra_stats: [max_total_weight] }
    medic:  { extra_stats: [heal] }
''';
